pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts1, uint256 ts2, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        ts1 = bound(ts1, 1, 98);
        ts2 = bound(ts2, ts1 + 1, 99);

        // keep block.number far above both timestamps: the mutant stores the
        // block number, which then locks the contract against future timestamps
        vm.roll(200);

        vm.deal(actor, 20 ether);

        // first call at timestamp ts1
        vm.warp(ts1);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // second call at a strictly later timestamp ts2 (still below block.number)
        vm.warp(ts2);
        vm.prank(actor);
        bool ok;
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // a later-timestamp call must always succeed: the lock is on timestamps,
        // never on block numbers
        assertTrue(ok);
    }
}

