pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Caller caller;

    function setUp() public { c = new C{value: 10 ether}(); caller = new Caller(); }

    function testFuzz_property(uint256 ts, uint256 bn) public {
        vm.assume(ts > 0);
        // any block number divisible by 15 triggers the payout rule in the reference
        bn = bound(bn, 0, type(uint256).max / 15) * 15;
        vm.roll(bn);
        vm.warp(ts);

        // fund the caller and route the 10-ether entry call through it
        vm.deal(address(caller), 10 ether);
        caller.hit(address(c), 10 ether);

        // general rule: an accepted call at a 15-divisible block drains c fully
        assertTrue(c.pastBlockTime() == ts && address(c).balance == 0);
    }
}

contract Caller {
    function hit(address target, uint256 amount) external payable {
        (bool ok, ) = target.call{value: amount}("");
        require(ok, "call failed");
    }
    receive() external payable {}
}

