pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint64 t) public {
        // admissible domain: any timestamp strictly after deployment (pastBlockTime starts at 0)
        t = uint64(bound(t, 1, type(uint64).max / 2));
        vm.warp(t);

        vm.deal(address(this), 20 ether);

        // drive c through its fallback via low-level call (fallback cannot be called by name)
        bool ok1;
        (ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call must succeed on P at a fresh timestamp");

        // second call in the SAME timestamp: the strict > guard must reject it
        bool ok2;
        (ok2, ) = address(c).call{value: 10 ether}("");

        // general rule: every successful call stores a strictly increasing timestamp,
        // so pastBlockTime equals the first call's timestamp and a same-timestamp call
        // cannot succeed; the mutant allows it (ok2 == true), breaking the invariant.
        assertTrue(!ok2 && c.pastBlockTime() == t);
    }
}
